def lora_parameter_count(d: int, k: int, r: int) -> tuple:
    full_params = d * k
    lora_params = r * (d + k)
    reduction_factor = round(full_params / lora_params, 2)
    return full_params, lora_params, reduction_factor

def lora_savings_percent(d: int, k: int, r: int) -> float:
    """Percent of full fine-tuning params LoRA avoids training."""
    full_params, lora_params, _ = lora_parameter_count(d, k, r)
    return round((1 - lora_params / full_params) * 100, 4)

print(lora_savings_percent(4096, 4096, 8))
